export function filterFoodDishes({
  destinationId = 'goa',
  query = '',
  diet = 'all',
  budget = 'all',
  minRating = 0,
  establishment = 'all',
  mustTryOnly = false
} = {}) {
  let list = FOOD_DISHES;

  if (destinationId && destinationId !== 'all') {
    const target = destinationId.toLowerCase();
    list = list.filter((d) => d.destinationId.toLowerCase() === target);

    if (list.length === 0) {
      list = FOOD_DISHES.filter((d) => d.destinationName.toLowerCase() === target);
    }
    if (list.length === 0) {
      list = FOOD_DISHES.filter((d) => d.destinationId === 'goa');
    }
  }

  if (mustTryOnly) {
    list = list.filter((d) => d.isMustTry);
  }

  if (diet && diet !== 'all') {
    list = list.filter((d) => d.diet.toLowerCase() === diet.toLowerCase());
  }

  if (establishment && establishment !== 'all') {
    list = list.filter((d) => d.establishment.toLowerCase().includes(establishment.toLowerCase()));
  }

  if (minRating > 0) {
    list = list.filter((d) => d.rating >= minRating);
  }

  if (budget === 'budget') {
    list = list.filter((d) => d.minPrice <= 200);
  } else if (budget === 'moderate') {
    list = list.filter((d) => d.minPrice > 200 && d.minPrice <= 450);
  } else if (budget === 'premium') {
    list = list.filter((d) => d.minPrice > 450);
  }

  if (query && query.trim()) {
    const q = query.toLowerCase().trim();
    list = list.filter((d) =>
      d.name.toLowerCase().includes(q) ||
      d.cuisine.toLowerCase().includes(q) ||
      d.establishment.toLowerCase().includes(q) ||
      d.destinationName.toLowerCase().includes(q) ||
      (d.tasteProfile && d.tasteProfile.toLowerCase().includes(q)) ||
      (d.description && d.description.toLowerCase().includes(q)) ||
      (d.ingredients && d.ingredients.some((ing) => ing.toLowerCase().includes(q))) ||
      (d.recommendedPlaces && d.recommendedPlaces.some((p) => p.name.toLowerCase().includes(q)))
    );
  }

  return list;
}

export function getTrailTemplates(destinationId = 'goa') {
  const destDishes = filterFoodDishes({ destinationId });
  const destObj = FOOD_DESTINATIONS.find((d) =>
    d.id.toLowerCase() === (destinationId || '').toLowerCase()
  ) || FOOD_DESTINATIONS[0];

  const mealTimes = ['10:30 AM', '1:15 PM', '4:45 PM', '7:30 PM'];

  const stops = destDishes.slice(0, 4).map((dish, idx) => {
    const place = dish.recommendedPlaces?.[0] || {
      name: dish.destinationName + ' Heritage Kitchen',
      address: 'Central Street, ' + dish.destinationName,
      lat: destObj.coordinates?.lat || 20.5937,
      lng: destObj.coordinates?.lng || 78.9629
    };
    return {
      stopNumber: idx + 1,
      dishId: dish.id,
      dishName: dish.name,
      restaurantName: place.name,
      dishImage: dish.image,
      address: place.address,
      mealType: dish.meal,
      suggestedTime: mealTimes[idx] || '1:00 PM',
      priceEstimate: '₹' + dish.minPrice,
      distanceToNext: idx < 3 ? ((1.2 + idx * 0.7).toFixed(1) + ' km (10 min)') : 'End of Trail',
      lat: place.lat,
      lng: place.lng,
      notes: place.highlight || ('Famous for authentic ' + dish.name)
    };
  });

  return [
    {
      id: destObj.id + '-signature-trail',
      destinationId: destObj.id,
      name: destObj.name + ' Signature Heritage Food Walk',
      tagline: 'Iconic street flavors, royal recipes & legendary local eateries',
      heroImage: destDishes[0]?.image || destObj.heroImage,
      totalStops: stops.length,
      estimatedHours: '3.5 Hours',
      approxDistance: (stops.length * 1.8).toFixed(1) + ' km',
      totalBudget: stops.reduce((acc, s) => acc + (parseInt(s.priceEstimate.replace(/\D/g, ''), 10) || 300), 0),
      highlights: ['Authentic signature dishes', 'Local heritage markets', 'Walking friendly route'],
      stops
    },
    {
      id: destObj.id + '-street-sweet-trail',
      destinationId: destObj.id,
      name: destObj.name + ' Street Bites & Sweet Delicacies',
      tagline: 'Crispy savory bites, artisan tea stops & iconic sweet desserts',
      heroImage: destDishes[1]?.image || destObj.heroImage,
      totalStops: Math.min(3, stops.length),
      estimatedHours: '2.5 Hours',
      approxDistance: (Math.min(3, stops.length) * 1.4).toFixed(1) + ' km',
      totalBudget: stops.slice(0, 3).reduce((acc, s) => acc + (parseInt(s.priceEstimate.replace(/\D/g, ''), 10) || 200), 0),
      highlights: ['Local bakeries & sweets', 'Quick street bites', 'Scenic walking streets'],
      stops: stops.slice(0, 3)
    }
  ];
}
